/**
 * Benchmark Career — клиентский портал «Нетворк».
 * Cloudflare Worker: вход по одноразовому коду на почту из карточки контакта (Resend),
 * данные только своего клиента (Zoho CRM, только чтение), многоуровневый кэш в KV.
 *
 * Привязки и переменные — см. README.md.
 */
const HTML = "<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex,nofollow\">\n<title>Личный кабинет · Benchmark Career</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@300;400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--teal:#8EBFC5;--teal-d:#3E7C85;--teal-dd:#2D6870;--gray:#7B7B7B;--ink:#2B3238;--mut:#6D767E;--line:#E3EAEC;--bg:#F5F8F9;--lilac:#B9A9E0;--sky:#7FB8D6;\n--ok:#1F7A55;--okb:#E2F4EB;--inf:#2A6A88;--infb:#E3F0F6;--warn:#8A5A00;--warnb:#FFF1D6;--wait:#5C6670;--waitb:#ECEFF1;--no:#9B4455;--nob:#F8E6EA}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 Montserrat,Inter,-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif}\nbutton,input,select{font:inherit;color:inherit}\nbutton{cursor:pointer}\na{color:var(--teal-d);text-decoration:none}a:hover{text-decoration:underline}\n.shell{width:min(1280px,calc(100% - 32px));margin:0 auto}\n.logo{height:52px;display:block}\n.hidden{display:none!important}\n\n/* ---------- вход ---------- */\n.login{min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(900px 500px at 85% -10%,#E4F0F2 0,transparent 60%),radial-gradient(700px 400px at -10% 110%,#EFEAFA 0,transparent 55%),var(--bg)}\n.lcard{width:min(440px,100%);background:#fff;border:1px solid var(--line);border-radius:20px;padding:34px 30px 28px;box-shadow:0 20px 50px #2d68700f}\n.lcard .logo{height:46px;margin-bottom:26px}\n.lcard h1{font-size:24px;font-weight:300;margin:0 0 6px;color:#555}\n.lcard h1 b{font-weight:600;color:var(--teal-d)}\n.lcard p{color:var(--mut);margin:0 0 20px;font-size:13px}\nlabel.f{display:block;font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--gray);margin-bottom:6px}\n.inp{width:100%;padding:13px 14px;border:1px solid #D5DEE1;border-radius:12px;background:#fff;font-size:15px;outline:none}\n.inp:focus{border-color:var(--teal);box-shadow:0 0 0 3px #8EBFC533}\n.codeinp{text-align:center;font-size:28px;letter-spacing:.5em;padding-left:.5em;font-weight:500}\n.btn{border:1px solid var(--line);background:#fff;border-radius:11px;padding:10px 16px;font-weight:600;font-size:13px}\n.btn:hover{background:#F4F8F9}\n.btn.pri{background:var(--teal-d);border-color:var(--teal-d);color:#fff;width:100%;padding:13px;font-size:14px;margin-top:14px}\n.btn.pri:hover{background:var(--teal-dd)}.btn:disabled{opacity:.55;cursor:default}\n.links{display:flex;justify-content:space-between;gap:10px;margin-top:14px;font-size:12.5px}\n.links button{background:none;border:0;color:var(--teal-d);padding:0}.links button:disabled{color:var(--mut)}\n.err{color:var(--no);font-size:12.5px;margin-top:10px;min-height:18px}\n.hint{font-size:12px;color:var(--mut);margin-top:16px;line-height:1.5}\n\n/* ---------- кабинет ---------- */\nheader.top{background:#fff;border-bottom:1px solid var(--line)}\n.topin{height:84px;display:flex;align-items:center;justify-content:space-between;gap:16px}\n.who{display:flex;align-items:center;gap:12px;color:var(--mut);font-size:12.5px}\n.ava{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;font-weight:600;color:#fff;background:linear-gradient(135deg,var(--lilac),var(--teal))}\n.who button{background:none;border:1px solid var(--line);border-radius:9px;padding:6px 11px;font-size:12px}\n.hero{background:linear-gradient(120deg,#2D6870 0,#3E7C85 55%,#5A9CA6 100%);color:#fff;padding:34px 0 30px;position:relative;overflow:hidden}\n.hero:before{content:\"\";position:absolute;right:-60px;top:-120px;width:420px;height:420px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#C9B6E4cc,#7FB8D6aa 60%,transparent 70%);opacity:.35}\n.hero:after{content:\"\";position:absolute;right:140px;bottom:-80px;width:200px;height:200px;border-radius:50%;border:1px solid #ffffff30}\n.eyebrow{font-size:10.5px;font-weight:600;letter-spacing:.2em;color:#D7ECEF;text-transform:uppercase}\n.hero h1{font-size:34px;font-weight:300;margin:10px 0 6px;line-height:1.15;position:relative}\n.hero h1 b{font-weight:600}\n.hero p{margin:0;color:#DCEBED;font-size:13px;position:relative}\n.tabsbar{background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:5}\n.tabs{display:flex;align-items:center;gap:30px}\n.tab{padding:17px 2px 15px;border:0;background:none;color:#8A949C;font-weight:600;font-size:13px;border-bottom:3px solid transparent}\n.tab i{font-style:normal;font-weight:400;margin-right:8px;opacity:.7}\n.tab.on{color:var(--teal-d);border-color:var(--teal)}\n.tabs .sp{flex:1}.tabs .upd{font-size:11.5px;color:#98A2AA}\nmain{padding:26px 0 60px}\n.sh{display:flex;justify-content:space-between;align-items:flex-end;gap:14px;margin-bottom:16px;flex-wrap:wrap}\n.sh h2{font-size:22px;font-weight:300;margin:0;color:#444}.sh p{margin:4px 0 0;color:var(--mut);font-size:12.5px}\n.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}\n.metric{background:#fff;border:1px solid var(--line);border-radius:14px;padding:16px 16px 14px;cursor:pointer;text-align:left;transition:.15s}\n.metric:hover{border-color:#B9CED2}.metric.on{border-color:var(--teal-d);background:#F1F8F9;box-shadow:0 0 0 2px #8EBFC544}\n.metric b{display:block;font-size:30px;font-weight:300;color:var(--teal-d);line-height:1.1;letter-spacing:-.02em}\n.metric span{display:block;font-size:11.5px;color:var(--mut);margin-top:6px;line-height:1.3}\n.metric em{font-style:normal;font-size:11px;color:var(--teal-d);margin-left:6px}\n.sheet{background:#fff;border:1px solid var(--line);border-radius:16px;margin-top:16px;overflow:hidden}\n.sheeth{padding:20px 20px 12px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:center}\n.sheeth h3{margin:0;font-size:16px;font-weight:600;color:#444}.sheeth p{margin:3px 0 0;font-size:12px;color:var(--mut)}\n.filters{padding:0 20px 14px;display:flex;gap:10px;flex-wrap:wrap}\n.filters .inp{padding:10px 12px;font-size:13px;border-radius:10px;width:auto}\n.filters .search{flex:1;min-width:240px}\n.cnt{align-self:center;font-size:12px;color:var(--mut);margin-left:auto}\n.ov{overflow-x:auto}\ntable{width:100%;border-collapse:collapse;min-width:900px}\nth{background:#F5F9FA;color:#79868D;font-size:10.5px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;text-align:left;padding:11px 14px;white-space:nowrap}\ntd{padding:13px 14px;border-top:1px solid var(--line);vertical-align:top}\ntd .co{font-weight:600;color:#3a434a}.sub{font-size:12px;color:var(--mut)}\ntd .ln{font-size:12px;margin-top:2px;display:inline-block}\n.chip{display:inline-block;padding:3px 10px;border-radius:12px;font-size:11.5px;font-weight:600;white-space:nowrap}\n.chip.ok{background:var(--okb);color:var(--ok)}.chip.inf{background:var(--infb);color:var(--inf)}.chip.warn{background:var(--warnb);color:var(--warn)}.chip.wait{background:var(--waitb);color:var(--wait)}.chip.no{background:var(--nob);color:var(--no)}\n.det{background:none;border:1px solid #D5DEE1;border-radius:9px;padding:6px 11px;font-size:12px;font-weight:600;color:var(--teal-d)}\n.det:hover{background:#F1F8F9}\ntr.dr td{background:#FAFCFC;padding:12px 14px 16px 28px}\n.tl{border-left:2px solid var(--teal);margin-left:5px;padding-left:16px}\n.tl .it{position:relative;padding:3px 0 10px}.tl .it:before{content:\"\";position:absolute;left:-23px;top:8px;width:10px;height:10px;border-radius:50%;background:linear-gradient(135deg,var(--lilac),var(--teal))}\n.tl .d{font-weight:600;font-size:12.5px}.tl .t{color:var(--mut);font-size:12.5px}\n.note{font-size:12px;color:var(--mut);margin:12px 20px 0}\n.empty{padding:44px 20px;text-align:center;color:var(--mut)}\n.gl{margin-top:16px}\n.gl summary{cursor:pointer;padding:16px 20px;font-weight:600;font-size:14px;color:#444;list-style:none}\n.gl summary:after{content:\"▾\";float:right;color:var(--mut)}\n.gl[open] summary:after{content:\"▴\"}\n.glr{display:grid;grid-template-columns:200px 1fr;gap:6px 18px;padding:0 20px 18px}\n.glr div:nth-child(odd){padding-top:2px}.glr div:nth-child(even){color:#46505a;font-size:13px;padding-bottom:8px;border-bottom:1px solid var(--line)}\n.two{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);gap:16px}\n.blk{padding:0 22px}.blk .l{font-size:10.5px;font-weight:600;letter-spacing:.1em;color:#79868D;text-transform:uppercase;padding-top:18px}\n.blk .x{padding:6px 0 18px;border-bottom:1px solid var(--line);white-space:pre-wrap}.blk:last-child .x{border:0}\n.mat{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--line);border-radius:12px;margin:0 20px 10px;color:inherit}\n.mat:hover{background:#F6FAFA;text-decoration:none}\n.mat .ic{width:40px;height:40px;border-radius:10px;background:#E8F2F4;color:var(--teal-d);font-weight:700;font-size:11px;display:grid;place-items:center}\n.toast{position:fixed;left:50%;bottom:20px;transform:translateX(-50%);background:#2B3238;color:#fff;padding:10px 16px;border-radius:10px;font-size:13px;z-index:50;max-width:90%}\n\n@media(max-width:980px){.metrics{grid-template-columns:repeat(3,1fr)}.two{grid-template-columns:1fr}}\n@media(max-width:760px){\n  .hero h1{font-size:26px}.metrics{grid-template-columns:repeat(2,1fr)}\n  table,thead,tbody,tr,td{display:block;min-width:0;width:100%}thead{display:none}\n  tr.r{border-top:1px solid var(--line);padding:12px 16px}tr.r td{border:0;padding:3px 0}\n  tr.r td[data-l]:before{content:attr(data-l);display:block;font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:#98A2AA;margin-top:6px}\n  tr.dr td{padding:10px 16px 14px}\n  .glr{grid-template-columns:1fr}.glr div:nth-child(odd){font-weight:600;border:0;padding-bottom:0}\n  .upd{display:none}.tabs{gap:22px}.who span{display:none}\n}\n</style>\n</head>\n<body>\n\n<!-- ===================== ВХОД ===================== -->\n<section id=\"login\" class=\"login hidden\">\n  <div class=\"lcard\">\n    <img class=\"logo\" src=\"data:image/png;base64,\" alt=\"benchmark career\">\n    <div id=\"s1\">\n      <h1>Личный <b>кабинет</b></h1>\n      <p>Введите почту, указанную в вашем профиле. Мы отправим на неё одноразовый код для входа.</p>\n      <label class=\"f\" for=\"em\">Электронная почта</label>\n      <input id=\"em\" class=\"inp\" type=\"email\" autocomplete=\"email\" inputmode=\"email\" placeholder=\"name@company.com\">\n      <button id=\"getcode\" class=\"btn pri\">Получить код</button>\n      <div id=\"e1\" class=\"err\"></div>\n      <div class=\"hint\">Доступ предоставляется клиентам программы «Стратегия Карьеры». Если письмо не пришло, проверьте папку «Спам» или напишите вашему консультанту.</div>\n    </div>\n    <div id=\"s2\" class=\"hidden\">\n      <h1>Введите <b>код</b></h1>\n      <p id=\"sent\">Мы отправили 6-значный код на почту.</p>\n      <label class=\"f\" for=\"cd\">Код из письма</label>\n      <input id=\"cd\" class=\"inp codeinp\" type=\"text\" inputmode=\"numeric\" autocomplete=\"one-time-code\" maxlength=\"6\" placeholder=\"······\">\n      <button id=\"login-btn\" class=\"btn pri\">Войти</button>\n      <div id=\"e2\" class=\"err\"></div>\n      <div class=\"links\"><button id=\"resend\" disabled>Отправить ещё раз</button><button id=\"chg\">Изменить почту</button></div>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== КАБИНЕТ ===================== -->\n<section id=\"app\" class=\"hidden\">\n  <header class=\"top\"><div class=\"shell topin\">\n    <img class=\"logo\" src=\"data:image/png;base64,\" alt=\"benchmark career\">\n    <div class=\"who\"><span>Личный кабинет · конфиденциально</span><div class=\"ava\" id=\"ava\"></div><button id=\"out\">Выйти</button></div>\n  </div></header>\n  <div class=\"hero\"><div class=\"shell\">\n    <div class=\"eyebrow\">Персональная карта нетворка · Стратегия карьеры</div>\n    <h1 id=\"hname\"></h1>\n    <p>Компании и лица, принимающие решения, с которыми мы работаем по вашей стратегии.</p>\n  </div></div>\n  <div class=\"tabsbar\"><div class=\"shell tabs\">\n    <button class=\"tab on\" data-t=\"net\"><i>01</i>Нетворк</button>\n    <button class=\"tab hidden\" data-t=\"str\"><i>02</i>Стратегия</button>\n    <span class=\"sp\"></span><span class=\"upd\" id=\"upd\"></span>\n  </div></div>\n\n  <main class=\"shell\">\n    <div id=\"t-net\">\n      <div class=\"sh\"><div><h2>Прогресс по целевому рынку</h2><p>Результаты работы с компаниями и лицами, принимающими решения</p></div>\n        <div><button class=\"btn\" id=\"refresh\">↻ Обновить</button></div></div>\n      <div class=\"metrics\" id=\"metrics\"></div>\n      <div class=\"sheet\">\n        <div class=\"sheeth\"><div><h3>Карта компаний и контактов</h3><p>Нажмите «Детали», чтобы увидеть историю касаний.</p></div></div>\n        <div class=\"filters\">\n          <input id=\"fq\" class=\"inp search\" type=\"search\" placeholder=\"Поиск: компания, контакт, должность, индустрия\">\n          <select id=\"fst\" class=\"inp\"><option value=\"\">Все статусы</option></select>\n          <select id=\"find\" class=\"inp\"><option value=\"\">Все индустрии</option></select>\n          <span class=\"cnt\" id=\"cnt\"></span>\n        </div>\n        <div class=\"ov\"><table id=\"tbl\"></table></div>\n        <div class=\"note hidden\" id=\"pend\"></div>\n        <div style=\"height:14px\"></div>\n      </div>\n      <details class=\"sheet gl\"><summary>Что значат статусы</summary><div class=\"glr\" id=\"gl\"></div></details>\n    </div>\n\n    <div id=\"t-str\" class=\"hidden\">\n      <div class=\"sh\"><div><h2>Позиционирование и материалы</h2><p>Стратегия выхода на целевые компании</p></div></div>\n      <div class=\"two\">\n        <div class=\"sheet\" style=\"margin:0\" id=\"blocks\"></div>\n        <div class=\"sheet\" style=\"margin:0\"><div class=\"sheeth\"><h3>Материалы</h3></div><div id=\"mats\" style=\"padding-bottom:8px\"></div></div>\n      </div>\n    </div>\n  </main>\n  <footer style=\"border-top:1px solid var(--line);background:#fff;padding:22px 0\"><div class=\"shell\" style=\"display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap\"><img class=\"logo\" style=\"height:40px\" src=\"data:image/png;base64,\" alt=\"benchmark career\"><span class=\"sub\">Конфиденциально. Информация предназначена только для вас.</span></div></footer>\n</section>\n<div id=\"toast\" class=\"toast hidden\"></div>\n\n<script>\nconst $=id=>document.getElementById(id);\nconst esc=s=>String(s==null?'':s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nasync function api(path,opt={}){\n  const o={credentials:'same-origin',headers:{},...opt};\n  if(opt.body){o.method='POST';o.headers={'Content-Type':'application/json','X-Requested-With':'nw'};o.body=JSON.stringify(opt.body)}\n  else if(opt.method==='POST'){o.headers={'X-Requested-With':'nw'}}\n  const r=await fetch(path,o);let j={};try{j=await r.json()}catch(e){}\n  return {ok:r.ok,status:r.status,j};\n}\nfunction toast(m){const t=$('toast');t.textContent=m;t.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.add('hidden'),3800)}\nconst fmtD=d=>{const m=String(d||'').match(/^(\\d{4})-(\\d\\d)-(\\d\\d)/);return m?`${m[3]}.${m[2]}.${m[1]}`:''};\nconst dShort=d=>{const m=String(d||'').match(/^\\d{4}-(\\d\\d)-(\\d\\d)/);return m?`${m[2]==='00'?'':m[2]}`&&`${m[2]}`:''};\n\n/* ---------------- вход ---------------- */\nlet email='';let cdTimer=null;\nfunction show(id){['login','app'].forEach(x=>$(x).classList.toggle('hidden',x!==id))}\nfunction startCooldown(){let n=60;const b=$('resend');b.disabled=true;clearInterval(cdTimer);\n  const tick=()=>{b.textContent=n>0?`Отправить ещё раз (${n} с)`:'Отправить ещё раз';if(n--<=0){clearInterval(cdTimer);b.disabled=false}};tick();cdTimer=setInterval(tick,1000)}\nfunction mask(e){const [u,d]=e.split('@');return (u.length>2?u.slice(0,2)+'•••':u[0]+'•••')+'@'+d}\nasync function sendCode(){\n  email=$('em').value.trim().toLowerCase();$('e1').textContent='';\n  if(!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(email)){$('e1').textContent='Проверьте адрес электронной почты';return}\n  $('getcode').disabled=true;\n  const r=await api('/api/otp/request',{body:{email}});\n  $('getcode').disabled=false;\n  if(!r.ok){$('e1').textContent=r.status===400?'Проверьте адрес электронной почты':'Не получилось отправить. Попробуйте чуть позже.';return}\n  $('sent').textContent=`Если эта почта есть в вашем профиле, мы отправили на неё 6-значный код (${mask(email)}). Код действует 10 минут.`;\n  $('s1').classList.add('hidden');$('s2').classList.remove('hidden');$('cd').value='';$('e2').textContent='';$('cd').focus();startCooldown();\n}\nasync function verify(){\n  const code=$('cd').value.replace(/\\D/g,'');if(code.length!==6){$('e2').textContent='Введите 6 цифр из письма';return}\n  $('login-btn').disabled=true;const r=await api('/api/otp/verify',{body:{email,code}});$('login-btn').disabled=false;\n  if(!r.ok){$('e2').textContent='Неверный или просроченный код. Запросите новый.';$('cd').select();return}\n  boot();\n}\n$('getcode').onclick=sendCode;$('em').onkeydown=e=>{if(e.key==='Enter')sendCode()};\n$('login-btn').onclick=verify;$('cd').onkeydown=e=>{if(e.key==='Enter')verify()};\n$('cd').oninput=e=>{const v=e.target.value.replace(/\\D/g,'').slice(0,6);e.target.value=v;if(v.length===6)verify()};\n$('resend').onclick=()=>{$('s2').classList.add('hidden');$('s1').classList.remove('hidden');sendCode()};\n$('chg').onclick=()=>{$('s2').classList.add('hidden');$('s1').classList.remove('hidden');$('em').focus()};\n$('out').onclick=async()=>{await api('/api/logout',{method:'POST'});location.reload()};\n\n/* ---------------- данные ---------------- */\nlet D=null;const F={q:'',st:'',ind:'',stage:''};const open=new Set();\nconst TONE=s=>({'Выход':'ok','Оффер':'ok','Интервью с компанией':'ok','Интро-встреча':'ok','Готовы рассматривать':'ok','Кадровый резерв':'warn','Приняли резюме':'inf','Первое касание/Отправили резюме':'inf','Нет ответа':'wait','Идут касания':'inf','В планах сделать первое касание':'wait','Знакомство с Benchmark':'wait','Не готовы рассматривать':'no','Отказ компании':'no','Отказ клиента':'no'}[s]||'inf');\nconst RANK=['Выход','Оффер','Интервью с компанией','Интро-встреча','Готовы рассматривать','Кадровый резерв','Приняли резюме','Первое касание/Отправили резюме','Идут касания','Нет ответа','Знакомство с Benchmark','В планах сделать первое касание','Не готовы рассматривать','Отказ компании','Отказ клиента'];\nconst rk=s=>{const i=RANK.indexOf(s);return i<0?50:i};\nconst NOT_ANS=new Set(['','В планах сделать первое касание','Знакомство с Benchmark','Первое касание/Отправили резюме','Идут касания','Нет ответа']);\nconst MEET=new Set(['Интро-встреча','Интервью с компанией','Оффер','Выход','Отказ компании']);\nconst STAGES=[\n {k:'comp',l:'Компаний',co:1,f:()=>true},\n {k:'lpr',l:'Контактов (ЛПР)',f:()=>true},\n {k:'sent',l:'Резюме направлено',f:s=>!['','В планах сделать первое касание','Знакомство с Benchmark'].includes(s)},\n {k:'ans',l:'Компаний ответили',co:1,f:s=>!NOT_ANS.has(s)},\n {k:'meet',l:'Компаний со встречей',co:1,f:s=>MEET.has(s)},\n {k:'wait',l:'Ждём ответа',f:s=>['Первое касание/Отправили резюме','Приняли резюме','Идут касания','Нет ответа'].includes(s)},\n];\nfunction stageOk(r){const t=STAGES.find(x=>x.k===F.stage);return !t||t.f(r.status)}\nfunction pass(r){\n  if(!stageOk(r))return false;\n  if(F.st&&r.status!==F.st)return false;if(F.ind&&r.industry!==F.ind)return false;\n  if(F.q){const h=(r.company+' '+r.lpr+' '+r.role+' '+r.industry+' '+(r.hyp||'')+' '+(r.geo||'')).toLowerCase();if(!F.q.split(' ').every(w=>h.includes(w)))return false}\n  return true;\n}\nfunction metrics(){\n  const rows=D.rows;const byC=new Map();rows.forEach(r=>{(byC.get(r.company)||byC.set(r.company,[]).get(r.company)).push(r.status)});\n  $('metrics').innerHTML=STAGES.map(t=>{\n    const v=t.k==='comp'?byC.size:t.co?[...byC.values()].filter(l=>l.some(t.f)).length:rows.filter(r=>t.f(r.status)).length;\n    const pc=(t.co&&t.k!=='comp'&&byC.size)?`<em>${Math.round(v/byC.size*100)}%</em>`:'';\n    return `<button class=\"metric${F.stage===t.k?' on':''}\" data-k=\"${t.k}\"><b>${v}${pc}</b><span>${t.l}</span></button>`}).join('');\n}\nfunction render(){\n  metrics();\n  const cols=D.columns||{};\n  const rows=D.rows.filter(pass);\n  const best=new Map();D.rows.forEach(r=>best.set(r.company,Math.min(best.get(r.company)??99,rk(r.status))));\n  rows.sort((a,b)=>(best.get(a.company)-best.get(b.company))||a.company.localeCompare(b.company,'ru')||(rk(a.status)-rk(b.status)));\n  let h=`<thead><tr><th>Компания / индустрия</th><th>Контакт / должность</th><th>Статус</th><th>Последнее касание</th>${cols.type?'<th>Тип контакта</th>':''}${cols.hyp||cols.geo?'<th>Гипотеза / география</th>':''}<th></th></tr></thead><tbody>`;\n  const span=5+(cols.type?1:0)+(cols.hyp||cols.geo?1:0);\n  for(const r of rows){\n    h+=`<tr class=\"r\"><td data-l=\"Компания\"><div class=\"co\">${esc(r.company)}</div><div class=\"sub\">${esc(r.industry)}</div></td>\n    <td data-l=\"Контакт\"><div class=\"co\">${esc(r.lpr)}</div><div class=\"sub\">${esc(r.role)}</div>${r.linkedin?`<a class=\"ln\" href=\"${esc(r.linkedin)}\" target=\"_blank\" rel=\"noopener noreferrer\">LinkedIn ↗</a>`:''}</td>\n    <td data-l=\"Статус\">${r.status?`<span class=\"chip ${TONE(r.status)}\">${esc(r.status)}</span>`:'<span class=\"sub\">—</span>'}</td>\n    <td data-l=\"Последнее касание\">${r.lastTouch?fmtD(r.lastTouch):'<span class=\"sub\">—</span>'}${r.touchCount?`<div class=\"sub\">касаний: ${r.touchCount}</div>`:''}</td>\n    ${cols.type?`<td data-l=\"Тип контакта\">${esc(r.type)}</td>`:''}${cols.hyp||cols.geo?`<td data-l=\"Гипотеза / география\">${esc(r.hyp||'')}<div class=\"sub\">${esc(r.geo||'')}</div></td>`:''}\n    <td><button class=\"det\" data-id=\"${esc(r.id)}\">${open.has(r.id)?'Свернуть ↑':'Детали ↓'}</button></td></tr>`;\n    if(open.has(r.id))h+=`<tr class=\"dr\"><td colspan=\"${span}\">${touchesHtml(r)}</td></tr>`;\n  }\n  $('tbl').innerHTML=rows.length?h+'</tbody>':'<tr><td class=\"empty\">Ничего не найдено. Измените фильтры.</td></tr>';\n  $('cnt').textContent=`${rows.length} из ${D.rows.length} контактов`;\n}\nfunction touchesHtml(r){\n  if(r.touches==null)return '<span class=\"sub\">Загружаю историю касаний…</span>';\n  if(!r.touches.length)return '<span class=\"sub\">Касаний по этому контакту пока нет.</span>';\n  return '<div class=\"tl\">'+r.touches.slice().reverse().map(t=>`<div class=\"it\"><div class=\"d\">${t.date?fmtD(t.date):'без даты'}</div><div class=\"t\">${t.portal?esc(t.portal):'Касание выполнено'}</div></div>`).join('')+'</div>';\n}\n$('metrics').addEventListener('click',e=>{const b=e.target.closest('[data-k]');if(!b)return;const k=b.dataset.k;F.stage=(F.stage===k||k==='comp'||k==='lpr')?'':k;render()});\n$('tbl').addEventListener('click',async e=>{\n  const b=e.target.closest('.det');if(!b)return;const id=b.dataset.id;\n  if(open.has(id)){open.delete(id);render();return}\n  open.add(id);render();\n  const r=D.rows.find(x=>x.id===id);\n  if(r&&r.touches==null){const x=await api('/api/touches?id='+encodeURIComponent(id));r.touches=x.ok?x.j.touches:[];r.touchCount=r.touches.length;r.lastTouch=r.touches.length?r.touches[r.touches.length-1].date:null;render()}\n});\n$('fq').oninput=e=>{F.q=e.target.value.trim().toLowerCase();render()};\n$('fst').onchange=e=>{F.st=e.target.value;render()};$('find').onchange=e=>{F.ind=e.target.value;render()};\n$('refresh').onclick=async()=>{\n  $('refresh').disabled=true;const r=await api('/api/refresh',{method:'POST'});$('refresh').disabled=false;\n  if(r.status===429){toast('Обновлять можно не чаще, чем раз в 15 минут');return}\n  if(!r.ok){toast('Не удалось обновить данные');return}\n  setData(r.j);toast('Данные обновлены');\n};\nfunction setData(j){\n  D=j;\n  const sts=[...new Set(D.rows.map(r=>r.status).filter(Boolean))].sort((a,b)=>rk(a)-rk(b));\n  $('fst').innerHTML='<option value=\"\">Все статусы</option>'+sts.map(s=>`<option>${esc(s)}</option>`).join('');\n  const ins=[...new Set(D.rows.map(r=>r.industry).filter(Boolean))].sort();\n  $('find').innerHTML='<option value=\"\">Все индустрии</option>'+ins.map(s=>`<option>${esc(s)}</option>`).join('');\n  $('hname').innerHTML=esc(D.client.name);$('ava').textContent=(D.client.name||'').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();\n  const m=D.ageMin||0;$('upd').textContent=D.stale?'Данные могут быть неактуальны':(m<2?'Данные обновлены только что':`Данные обновлены ${m<60?m+' мин':Math.round(m/60)+' ч'} назад`);\n  $('pend').classList.toggle('hidden',!D.pending);if(D.pending)$('pend').textContent='История касаний части контактов подгружается при нажатии «Детали».';\n  $('gl').innerHTML=D.glossary.map(g=>`<div><span class=\"chip ${TONE(g[0])}\">${esc(g[0])}</span></div><div>${esc(g[1])}</div>`).join('');\n  render();\n}\ndocument.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('on',x===b));$('t-net').classList.toggle('hidden',b.dataset.t!=='net');$('t-str').classList.toggle('hidden',b.dataset.t!=='str')});\n\nasync function loadStrategy(){\n  const r=await api('/api/strategy');if(!r.ok)return;const s=r.j;\n  if(!(s.blocks&&s.blocks.length)&&!(s.materials&&s.materials.length))return;\n  document.querySelector('.tab[data-t=str]').classList.remove('hidden');\n  $('blocks').innerHTML='<div class=\"sheeth\"><h3>Персонализация стратегии</h3></div>'+(s.blocks||[]).map(b=>`<div class=\"blk\"><div class=\"l\">${esc(b.label)}</div><div class=\"x\">${esc(b.text)}</div></div>`).join('');\n  $('mats').innerHTML=(s.materials||[]).map(m=>{const ext=(m.name.split('.').pop()||'').slice(0,4).toUpperCase();return `<a class=\"mat\" href=\"/api/material?id=${encodeURIComponent(m.id)}\"><div class=\"ic\">${esc(ext)}</div><div><div class=\"co\">${esc(m.name)}</div><div class=\"sub\">${fmtD(m.date)}</div></div></a>`}).join('')||'<div class=\"empty\">Материалы появятся позже</div>';\n}\nasync function boot(){\n  const s=await api('/api/session');\n  if(!s.j.auth){show('login');return}\n  show('app');\n  const r=await api('/api/network');\n  if(r.status===401){show('login');return}\n  if(!r.ok){$('tbl').innerHTML='<tr><td class=\"empty\">Данные временно недоступны. Попробуйте обновить страницу через несколько минут.</td></tr>';return}\n  setData(r.j);loadStrategy();\n}\nboot();\n</script>\n</body>\n</html>\n"; // подставляется build.js

/* ============================ Настройки ============================ */
const DC = {
  eu: ['https://accounts.zoho.eu', 'https://www.zohoapis.eu'],
  com: ['https://accounts.zoho.com', 'https://www.zohoapis.com'],
  in: ['https://accounts.zoho.in', 'https://www.zohoapis.in'],
  au: ['https://accounts.zoho.com.au', 'https://www.zohoapis.com.au'],
  jp: ['https://accounts.zoho.jp', 'https://www.zohoapis.jp'],
  ca: ['https://accounts.zohocloud.ca', 'https://www.zohoapis.ca'],
  sa: ['https://accounts.zoho.sa', 'https://www.zohoapis.sa'],
};
const cfg = (env) => ({
  dc: DC[(env.ZOHO_DC || 'eu').toLowerCase()] || DC.eu,
  cacheMin: Number(env.CACHE_TTL_MIN || 60),          // «свежесть» данных клиента
  staleHours: Number(env.STALE_HOURS || 72),          // сколько держим на случай сбоя
  maxPrefetch: Number(env.MAX_PREFETCH || 40),        // сколько записей за раз дочитываем из Zoho (50 — лимит бесплатного тарифа Cloudflare)
  dailyBudget: Number(env.DAILY_ZOHO_BUDGET || 3000), // жёсткий потолок обращений к Zoho в сутки
  sessionHours: Number(env.SESSION_HOURS || 168),
  otpMinutes: Number(env.OTP_MINUTES || 10),
  showComments: String(env.SHOW_TOUCH_COMMENTS || '0') === '1',
  flagField: env.PORTAL_FLAG_FIELD || '',             // api-имя чекбокса «Доступ к порталу» в Contacts (рекомендуется)
  extra: { // необязательные поля Network для колонок «Тип контакта», «Гипотеза / география»
    type: env.NET_FIELD_TYPE || '', hyp: env.NET_FIELD_HYPOTHESIS || '', geo: env.NET_FIELD_GEO || '',
  },
  personalization: safeJSON(env.PERSONALIZATION_FIELDS, []),
  materialsPrefix: env.MATERIALS_PREFIX || 'CLIENT_',
  from: env.MAIL_FROM || '',
  brand: env.PORTAL_NAME || 'Benchmark Career',
});
function safeJSON(s, d) { try { return s ? JSON.parse(s) : d; } catch { return d; } }

