/* ============================ Утилиты ============================ */
const enc = new TextEncoder();
const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
async function hmac(secret, msg) {
  const k = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return hex(await crypto.subtle.sign('HMAC', k, enc.encode(msg)));
}
function timingSafeEqual(a, b) {
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
const code6 = () => String(crypto.getRandomValues(new Uint32Array(1))[0] % 1000000).padStart(6, '0');
const token = () => hex(crypto.getRandomValues(new Uint8Array(32)));
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const q = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
const normEmail = (e) => String(e || '').trim().toLowerCase();
const validEmail = (e) => /^[^\s@]{1,64}@[^\s@]{1,255}\.[^\s@]{2,}$/.test(e) && e.length <= 254;
const today = () => new Date().toISOString().slice(0, 10).replace(/-/g, '');

const SEC = {
  'Content-Security-Policy': "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; script-src 'self' 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'",
  'X-Content-Type-Options': 'nosniff', 'X-Frame-Options': 'DENY', 'Referrer-Policy': 'no-referrer',
  'Strict-Transport-Security': 'max-age=31536000; includeSubDomains', 'X-Robots-Tag': 'noindex, nofollow, noarchive',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
};
const json = (obj, status = 200, extra = {}) =>
  new Response(JSON.stringify(obj), { status, headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', ...SEC, ...extra } });

async function kvGet(env, key) { const v = await env.NW.get(key); return v ? JSON.parse(v) : null; }
async function kvPut(env, key, val, ttlSec) { await env.NW.put(key, JSON.stringify(val), { expirationTtl: Math.max(60, Math.ceil(ttlSec)) }); }

/** Фиксированное окно: вернуть false, если лимит превышен. */
async function limit(env, key, max, windowSec) {
  const w = Math.floor(Date.now() / 1000 / windowSec);
  const k = `rl:${key}:${w}`;
  const n = Number((await env.NW.get(k)) || 0);
  if (n >= max) return false;
  await env.NW.put(k, String(n + 1), { expirationTtl: windowSec + 60 });
  return true;
}

/* ============================ Zoho CRM ============================ */
class BudgetError extends Error {}
async function spend(env, n = 1) {
  const c = cfg(env); const k = `budget:${today()}`;
  const used = Number((await env.NW.get(k)) || 0);
  if (used + n > c.dailyBudget) throw new BudgetError('daily budget');
  await env.NW.put(k, String(used + n), { expirationTtl: 90000 });
}
async function accessToken(env, force = false) {
  if (!force) { const t = await kvGet(env, 'zoho:token'); if (t && t.exp > Date.now() + 60000) return t.v; }
  const c = cfg(env);
  const r = await fetch(`${c.dc[0]}/oauth/v2/token`, {
    method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ refresh_token: env.ZOHO_REFRESH_TOKEN, client_id: env.ZOHO_CLIENT_ID, client_secret: env.ZOHO_CLIENT_SECRET, grant_type: 'refresh_token' }),
  });
  const j = await r.json().catch(() => ({}));
  if (!j.access_token) throw new Error('zoho token: ' + (j.error || r.status));
  await kvPut(env, 'zoho:token', { v: j.access_token, exp: Date.now() + (j.expires_in || 3600) * 1000 }, (j.expires_in || 3600));
  return j.access_token;
}
async function zoho(env, path, { method = 'GET', body, raw = false } = {}) {
  await spend(env, 1);
  const c = cfg(env);
  for (let attempt = 0; attempt < 2; attempt++) {
    const t = await accessToken(env, attempt > 0);
    const r = await fetch(`${c.dc[1]}/crm/v8/${path}`, {
      method, headers: { Authorization: `Zoho-oauthtoken ${t}`, ...(body ? { 'Content-Type': 'application/json' } : {}) }, body: body ? JSON.stringify(body) : undefined,
    });
    if (r.status === 401 && attempt === 0) continue;
    if (r.status === 204) return raw ? r : null;
    if (raw) return r;
    if (!r.ok) throw new Error(`zoho ${r.status} ${path.slice(0, 60)}`);
    return r.json();
  }
}
async function coql(env, select) {
  const j = await zoho(env, 'coql', { method: 'POST', body: { select_query: select } });
  return (j && j.data) || [];
}
async function coqlAll(env, select, max = 1000) {
  let out = [];
  for (let off = 0; off < max; off += 200) {
    const part = await coql(env, `${select} limit ${off}, 200`);
    out = out.concat(part);
    if (part.length < 200) break;
  }
  return out;
}
async function byIds(env, module, fields, ids) {
  ids = [...new Set(ids.filter(Boolean))]; const out = {};
  for (let i = 0; i < ids.length; i += 50) {
    const rows = await coql(env, `select ${fields} from ${module} where id in (${ids.slice(i, i + 50).map((x) => `'${q(x)}'`).join(',')}) limit 0, 50`);
    rows.forEach((r) => { out[r.id] = r; });
  }
  return out;
}

/** Контакт по e-mail. Допуск: ровно один контакт с таким e-mail + (флаг доступа, если задан, иначе наличие записей Network как клиента). */
async function findContact(env, email) {
  const c = cfg(env);
  const flag = c.flagField ? `, ${c.flagField}` : '';
  const rows = await coql(env, `select id, Full_Name, Email${flag} from Contacts where Email = '${q(email)}' limit 0, 5`);
  const ok = rows.filter((r) => normEmail(r.Email) === email && (!c.flagField || r[c.flagField] === true));
  if (ok.length !== 1) return null;
  if (!c.flagField) { // без флага: доступ только у клиентов, у которых есть нетворк
    const has = await coql(env, `select id from Network where Candidate_Contact = '${q(ok[0].id)}' limit 0, 1`);
    if (!has.length) return null;
  }
  return ok[0];
}

/* ============================ Данные клиента (с кэшем) ============================ */
function shapeRow(c, n, ent, touchCache) {
  const lp = ent.con[n.Recommended_To && n.Recommended_To.id] || {};
  const ac = ent.acc[n.Account_Name && n.Account_Name.id] || {};
  const st = n.Network_Status && n.Network_Status !== '-None-' ? n.Network_Status : '';
  const tc = touchCache[n.id];
  const touches = tc ? tc.t : null;
  const last = touches && touches.length ? touches[touches.length - 1].date : null;
  return {
    id: n.id,
    company: ac.Account_Name || (n.Account_Name && n.Account_Name.name) || '—',
    industry: ac.Industry || '',
    lpr: lp.Full_Name || (n.Recommended_To && n.Recommended_To.name) || '',
    role: lp.Title || '',
    linkedin: lp.LinkedIn || '',
    status: LABEL[st] || st,
    type: c.extra.type ? n[c.extra.type] || '' : undefined,
    hyp: c.extra.hyp ? n[c.extra.hyp] || '' : undefined,
    geo: c.extra.geo ? n[c.extra.geo] || '' : undefined,
    touchCount: touches ? touches.length : null,
    lastTouch: last,
    touches: touches ? touches.map((t) => shapeTouch(c, t)) : null,
  };
}
const shapeTouch = (c, t) => ({ date: t.date, type: t.type || '', answer: t.answer || '', comment: c.showComments ? t.comment || '' : '', portal: t.portal || '' });

async function fetchTouches(env, id) {
  const j = await zoho(env, `Network/${id}`);
  const rec = (j && j.data && j.data[0]) || {};
  const t = (rec.LinkingModule7 || []).map((x) => ({ date: x.field || null, comment: x.field1 || '', portal: x.field4 || '', type: x.field2 || '', answer: x.field3 && x.field3 !== '-None-' ? x.field3 : '' }))
    .sort((a, b) => String(a.date || '').localeCompare(String(b.date || '')));
  return { mt: rec.Modified_Time || '', t };
}

async function buildClient(env, contact) {
  const c = cfg(env);
  const extra = ['type', 'hyp', 'geo'].map((k) => c.extra[k]).filter(Boolean).join(', ');
  const nets = (await coqlAll(env,
    `select id, Name, Network_Status, Recommended_To, Account_Name, Modified_Time${extra ? ', ' + extra : ''} from Network where Candidate_Contact = '${q(contact.id)}' order by Created_Time asc`))
    .filter((n) => !HIDDEN.has(n.Network_Status));
  const [con, acc] = await Promise.all([
    byIds(env, 'Contacts', 'id, Full_Name, Title, LinkedIn', nets.map((n) => n.Recommended_To && n.Recommended_To.id)),
    byIds(env, 'Accounts', 'id, Account_Name, Industry', nets.map((n) => n.Account_Name && n.Account_Name.id)),
  ]);
  // Кэш касаний по записи: перечитываем только если Modified_Time изменился
  const touchCache = {}; const need = [];
  for (const n of nets) {
    const tc = await kvGet(env, `tch2:${n.id}`);
    if (tc && tc.mt === n.Modified_Time) touchCache[n.id] = tc; else need.push(n);
  }
  let pending = 0;
  const batch = need.slice(0, c.maxPrefetch);
  pending = need.length - batch.length;
  for (let i = 0; i < batch.length; i += 6) {
    await Promise.all(batch.slice(i, i + 6).map(async (n) => {
      try {
        const r = await fetchTouches(env, n.id);
        // mt берём из списка, чтобы сравнение при следующем обновлении было с тем же значением
        touchCache[n.id] = { mt: n.Modified_Time, t: r.t };
        await kvPut(env, `tch2:${n.id}`, touchCache[n.id], 60 * 60 * 24 * 90);
      } catch (e) { if (e instanceof BudgetError) throw e; pending++; }
    }));
  }
  const rows = nets.map((n) => shapeRow(c, n, { con, acc }, touchCache));
  return {
    client: { name: contact.Full_Name || '' }, updatedAt: new Date().toISOString(), pending, rows,
    columns: { type: !!c.extra.type, hyp: !!c.extra.hyp, geo: !!c.extra.geo }, glossary: GLOSSARY, brand: c.brand,
    _netMt: Object.fromEntries(nets.map((n) => [n.id, n.Modified_Time])),
  };
}

/** Кэш с запасом на случай сбоя и защитой от «стада» одновременных обновлений. */
async function getClient(env, ctx, contact, { force = false } = {}) {
  const c = cfg(env); const key = `data2:${contact.id}`;
  const hit = await kvGet(env, key);
  const age = hit ? (Date.now() - hit.at) / 60000 : Infinity;
  if (hit && !force && age < c.cacheMin) return { ...hit.p, cached: true, ageMin: Math.round(age) };
  const lock = await env.NW.get(`lock:${contact.id}`);
  if (lock && hit) return { ...hit.p, cached: true, ageMin: Math.round(age) };
  await env.NW.put(`lock:${contact.id}`, '1', { expirationTtl: 60 });
  try {
    const p = await buildClient(env, contact);
    await kvPut(env, key, { at: Date.now(), p }, c.staleHours * 3600);
    return { ...p, cached: false, ageMin: 0 };
  } catch (e) {
    console.log(JSON.stringify({ evt: 'refresh_failed', err: String(e && e.message) }));
    if (hit) return { ...hit.p, cached: true, stale: true, ageMin: Math.round(age) };
    throw e;
  } finally { await env.NW.delete(`lock:${contact.id}`); }
}

async function ownRow(env, ctx, contact, rid) {
  const data = await getClient(env, ctx, contact);
  return data.rows.find((r) => r.id === rid) ? data : null;
}

/* ============================ Стратегия и материалы ============================ */
async function getStrategy(env, contact) {
  const c = cfg(env); const key = `str:${contact.id}`;
  const hit = await kvGet(env, key);
  if (hit && Date.now() - hit.at < 6 * 3600 * 1000) return hit.p;
  const fields = c.personalization.map((f) => f.field).filter(Boolean);
  const out = { blocks: [], materials: [] };
  try {
    if (fields.length) {
      const j = await zoho(env, `Contacts/${contact.id}?fields=${fields.join(',')}`);
      const rec = (j && j.data && j.data[0]) || {};
      out.blocks = c.personalization.map((f) => ({ label: f.label, text: String(rec[f.field] || '') })).filter((b) => b.text.trim());
    }
    const a = await zoho(env, `Contacts/${contact.id}/Attachments?fields=id,File_Name,Size,Created_Time`);
    out.materials = ((a && a.data) || []).filter((x) => String(x.File_Name || '').startsWith(c.materialsPrefix))
      .map((x) => ({ id: x.id, name: String(x.File_Name).slice(c.materialsPrefix.length), size: x.Size || 0, date: String(x.Created_Time || '').slice(0, 10) }));
  } catch (e) { if (hit) return hit.p; if (!(e instanceof BudgetError)) console.log('strategy err', String(e && e.message)); }
  await kvPut(env, key, { at: Date.now(), p: out }, 24 * 3600);
  return out;
}

/* ============================ Вход: одноразовый код ============================ */
async function sendMail(env, to, code) {
  const c = cfg(env);
  const orig = to;
  if (env.OTP_REDIRECT_TO) to = String(env.OTP_REDIRECT_TO).trim(); // тестовый режим: все коды уходят на этот адрес
  const html = `<div style="font-family:Arial,sans-serif;max-width:480px;margin:auto;padding:24px;color:#2B3238">
  <div style="font-size:22px;letter-spacing:1px;color:#7B7B7B">benchmark <span style="color:#6FA9B1">career</span></div>
  ${orig !== to ? `<p style="color:#8a5a00;background:#fff1d6;padding:8px 12px;border-radius:8px">ТЕСТОВЫЙ РЕЖИМ: код для клиента ${esc(orig)}</p>` : ''}<p style="margin:24px 0 8px">Ваш код для входа в личный кабинет:</p>
  <div style="font-size:34px;letter-spacing:8px;font-weight:600;color:#3E7C85;background:#F1F7F8;border-radius:12px;padding:16px;text-align:center">${esc(code)}</div>
  <p style="color:#6D767E;font-size:13px;margin-top:20px">Код действует ${c.otpMinutes} минут. Если вы не запрашивали вход, просто проигнорируйте это письмо.</p></div>`;
  const r = await fetch('https://api.resend.com/emails', {
    method: 'POST', headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ from: c.from, to: [to], subject: `Код входа ${code} · ${c.brand}${orig !== to ? ' · для ' + orig : ''}`, html, text: `Ваш код для входа: ${code}. Действует ${c.otpMinutes} минут.` }),
  });
  if (!r.ok) console.log(JSON.stringify({ evt: 'mail_failed', status: r.status }));
}

async function requestOtp(env, ctx, email, ip) {
  const c = cfg(env);
  if (!(await limit(env, `ip:${ip}`, 20, 3600))) return;
  if (!(await limit(env, `em1:${email}`, 1, 60))) return;      // не чаще раза в минуту
  if (!(await limit(env, `em5:${email}`, 5, 3600))) return;    // не более 5 в час
  const contact = await findContact(env, email);
  if (!contact) { console.log(JSON.stringify({ evt: 'otp_unknown_email' })); return; }
  const code = code6();
  await kvPut(env, `otp:${email}`, { h: await hmac(env.OTP_SECRET, `${email}:${code}`), exp: Date.now() + c.otpMinutes * 60000, tries: 0, cid: contact.id, name: contact.Full_Name }, c.otpMinutes * 60 + 60);
  await sendMail(env, email, code);
}

async function verifyOtp(env, email, code, ip) {
  const c = cfg(env);
  if (!(await limit(env, `v:${ip}`, 30, 3600))) return null;
  const o = await kvGet(env, `otp:${email}`);
  if (!o || o.exp < Date.now()) return null;
  if (o.tries >= 5) { await env.NW.delete(`otp:${email}`); return null; }
  const h = await hmac(env.OTP_SECRET, `${email}:${code}`);
  if (!timingSafeEqual(h, o.h)) {
    o.tries += 1;
    if (o.tries >= 5) await env.NW.delete(`otp:${email}`); else await kvPut(env, `otp:${email}`, o, Math.ceil((o.exp - Date.now()) / 1000));
    return null;
  }
  await env.NW.delete(`otp:${email}`); // одноразовый
  const tok = token();
  await kvPut(env, `sess:${await hmac(env.OTP_SECRET, tok)}`, { cid: o.cid, name: o.name, email, exp: Date.now() + c.sessionHours * 3600000 }, c.sessionHours * 3600);
  return { tok, cid: o.cid };
}

async function getSession(env, req) {
  const m = (req.headers.get('Cookie') || '').match(/(?:^|;\s*)__Host-nw=([a-f0-9]{64})/);
  if (!m) return null;
  const s = await kvGet(env, `sess:${await hmac(env.OTP_SECRET, m[1])}`);
  if (!s || s.exp < Date.now()) return null;
  return { ...s, _key: `sess:${await hmac(env.OTP_SECRET, m[1])}` };
}

/* ============================ Маршруты ============================ */
export default {
  async fetch(req, env, ctx) {
    const url = new URL(req.url);
    const path = url.pathname;
    try {
      if (req.method === 'GET' && (path === '/' || path === '/index.html'))
        return new Response(HTML, { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', ...SEC } });
      if (path === '/healthz') return json({ ok: true });
      if (!path.startsWith('/api/')) return new Response('Not found', { status: 404, headers: SEC });

      if (req.method === 'POST') { // защита от CSRF
        const o = req.headers.get('Origin');
        if (o && new URL(o).host !== url.host) return json({ error: 'forbidden' }, 403);
        if (req.headers.get('X-Requested-With') !== 'nw') return json({ error: 'forbidden' }, 403);
      }
      const ip = req.headers.get('CF-Connecting-IP') || (req.headers.get('X-Real-IP') || (req.headers.get('X-Forwarded-For') || '').split(',')[0].trim()) || 'local';
      const cookie = (v, age) => `__Host-nw=${v}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${age}`;

      if (path === '/api/otp/request' && req.method === 'POST') {
        const b = await req.json().catch(() => ({}));
        const email = normEmail(b.email);
        if (!validEmail(email)) return json({ error: 'bad_email' }, 400);
        ctx.waitUntil(requestOtp(env, ctx, email, ip).catch((e) => console.log('otp err', String(e && e.message))));
        return json({ ok: true }); // ответ одинаков для любой почты
      }
      if (path === '/api/otp/verify' && req.method === 'POST') {
        const b = await req.json().catch(() => ({}));
        const email = normEmail(b.email); const code = String(b.code || '').replace(/\D/g, '');
        if (!validEmail(email) || code.length !== 6) return json({ error: 'bad_code' }, 400);
        const r = await verifyOtp(env, email, code, ip);
        if (!r) return json({ error: 'bad_code' }, 401);
        return json({ ok: true }, 200, { 'Set-Cookie': cookie(r.tok, cfg(env).sessionHours * 3600) });
      }

      const s = await getSession(env, req);
      if (path === '/api/session') return s ? json({ auth: true, name: s.name }) : json({ auth: false });
      if (!s) return json({ error: 'auth' }, 401);
      const contact = { id: s.cid, Full_Name: s.name };

      if (path === '/api/logout' && req.method === 'POST') {
        await env.NW.delete(s._key);
        return json({ ok: true }, 200, { 'Set-Cookie': cookie('', 0) });
      }
      if (path === '/api/network' && req.method === 'GET') {
        const d = await getClient(env, ctx, contact);
        const { _netMt, ...out } = d; return json(out);
      }
      if (path === '/api/refresh' && req.method === 'POST') { // ручное обновление — не чаще раза в 15 минут
        if (!(await limit(env, `rf:${s.cid}`, 1, 900))) return json({ error: 'too_soon' }, 429);
        const d = await getClient(env, ctx, contact, { force: true });
        const { _netMt, ...out } = d; return json(out);
      }
      if (path === '/api/touches' && req.method === 'GET') { // догрузка касаний отдельной записи
        const rid = url.searchParams.get('id') || '';
        const d = await ownRow(env, ctx, contact, rid);
        if (!d) return json({ error: 'not_found' }, 404);
        const row = d.rows.find((r) => r.id === rid);
        if (row.touches) return json({ touches: row.touches });
        const c = cfg(env); const r = await fetchTouches(env, rid);
        await kvPut(env, `tch2:${rid}`, { mt: (d._netMt || {})[rid] || r.mt, t: r.t }, 60 * 60 * 24 * 90);
        return json({ touches: r.t.map((t) => shapeTouch(c, t)) });
      }
      if (path === '/api/strategy' && req.method === 'GET') return json(await getStrategy(env, contact));
      if (path === '/api/material' && req.method === 'GET') {
        const id = url.searchParams.get('id') || '';
        const st = await getStrategy(env, contact);
        const m = st.materials.find((x) => x.id === id);
        if (!m) return json({ error: 'not_found' }, 404);
        const r = await zoho(env, `Contacts/${contact.id}/Attachments/${id}`, { raw: true });
        if (!r || !r.ok) return json({ error: 'unavailable' }, 502);
        return new Response(r.body, { headers: { 'Content-Type': r.headers.get('Content-Type') || 'application/octet-stream', 'Content-Disposition': `attachment; filename*=UTF-8''${encodeURIComponent(m.name)}`, 'Cache-Control': 'private, no-store', ...SEC } });
      }
      return json({ error: 'not_found' }, 404);
    } catch (e) {
      console.log(JSON.stringify({ evt: 'error', err: String(e && e.message) }));
      if (e instanceof BudgetError) return json({ error: 'busy', message: 'Данные временно недоступны, попробуйте позже' }, 503);
      return json({ error: 'server' }, 500);
    }
  },
};
